using System;
using System.Collections.Generic;
using System.Text;
using AutoMapper;
using NovaExpediente.Application.Afiliacion.Queries.GetAfiliacionDetalle;
using NovaExpediente.Application.Common.Mappings;
using NovaExpediente.Common;
using NovaExpediente.Domain.Entities;

namespace NovaExpediente.Application.Colaboradores.Queries.GetDetalleColaborador
{
    public class ColaboradorDto : IMapFrom<Colaborador>
    {
        private readonly IDateTime _dateTime;

        public ColaboradorDto()
        {
            _dateTime = new MachineDateTime();
        }

        public int IDCOLABORADOR { get; set; }
        public int IDPUESTO { get; set; }
        public int IDPAISORIGEN { get; set; }
        public int IDPAISRESIDENCIA { get; set; }
        public int IDUSUARIOCREA { get; set; }
        public int? IDUSUARIOMODIFICA { get; set; }
        public int? IDCANTON { get; set; }
        public int? IDAREAORGANIZATIVA { get; set; }
        public int? IDDELIVERYMANAGER { get; set; }
        public int? IDCLIENTE { get; set; }
        public int IDPAISFERIADO { get; set; }


        public string IDENTIFICACION { get; set; }
        public string NOMBRE { get; set; }
        public string PRIMERAPELLIDO { get; set; }
        public string SEGUNDOAPELLIDO { get; set; }
        public DateTime FECHANACIMIENTO { get; set; }
        public char GENERO { get; set; }
        public DateTime FECHAINGRESO { get; set; }
        public string DIRECCION { get; set; }

        public string CELULAR { get; set; }
        public string TELEFONO { get; set; }
        public string CORREO { get; set; }
        public string CORREOPERSONAL { get; set; }
        public string RESENAPERFIL { get; set; }
        public string NUMEROCPIC { get; set; }
        public string CERTIFICADOCPIC { get; set; }
        public string RAMAESPECIALIDAD { get; set; }
        public bool ACTIVO { get; set; }
        public string FOTO { get; set; }
        public char ESTADOCIVIL { get; set; }
        public string TELEFONOEMERGENCIA { get; set; }
        public string PERSONALLAMAR { get; set; }
        public int NUMEROHIJOS { get; set; }
        public DateTime FECHACREACION { get; set; }
        public DateTime? FECHAMODIFICACION { get; set; }
        //public timestamp CAMBIO { get; set; } //add nest?
        public DateTime INICIOVERSION
        { get; set; }
        public DateTime FINVERSION { get; set; }

        public string Puesto { get; set; }
        public string PaisOrigen { get; set; }
        public string PaisResidencia { get; set; }
        public string PaisFeriado { get; set; }
        public string Canton { get; set; }

        public string Edad { get; set; }
        public string Antiguedad { get; set; }
        public string AreaOrganizativa { get; set; }
        public string DeliveryManager { get; set; }
        public int IdDeliveryManager { get; set; }
        public int IDEMPRESACORPORACION { get; set; }
        public string EmpresaCorporacion { get; set; }

        public string UbicadoEn { get; set; }
        public string NombreCompleto { get; set; }

        public string CIUDADRESIDENCIA { get; set; }

        public bool ESDELIVERYMANAGER { get; set; }

        public string CODIGOPOSTAL { get; set; }
        public int? IDNOMINA { get; set; }
        public bool ESSERVICIOPROFESIONAL { get; set; }
        public bool SOLICITAVACACIONES { get; set; }
        public int? VACACIONESDIASANUALES { get; set; }

        public decimal SALDOVACACIONES { get; set; }
        public string Cliente { get; set; }


        public List<AfiliacionColaboradorDto> Afiliaciones { get; set; }

        public void Mapping(Profile profile)
        {
            profile.CreateMap<Colaborador, ColaboradorDto>()
                .ForMember(d => d.IDCOLABORADOR, opt => opt.MapFrom(s => s.IDCOLABORADOR))
                .ForMember(d => d.IDCLIENTE, opt => opt.MapFrom(s => s.IDCLIENTE))
                .ForMember(d => d.NOMBRE, opt => opt.MapFrom(s => s.NOMBRE))
                .ForMember(d => d.NombreCompleto, opt => opt.MapFrom(s => s.NOMBRE.Trim() + " " + s.PRIMERAPELLIDO.Trim() + " " + s.SEGUNDOAPELLIDO.Trim()))
                .ForMember(d => d.Puesto, opt => opt.MapFrom(s => s.Puesto != null ? s.Puesto.NOMBRE : ""))
                .ForMember(d => d.Cliente, opt => opt.MapFrom(s => s.Cliente != null ? s.Cliente.NOMBRE : ""))
                .ForMember(d => d.PaisOrigen, opt => opt.MapFrom(s => s.PaisOrigen != null ? s.PaisOrigen.NOMBRE : ""))
                .ForMember(d => d.PaisResidencia, opt => opt.MapFrom(s => s.PaisResidencia != null ? s.PaisResidencia.NOMBRE : ""))
                .ForMember(d => d.PaisFeriado, opt => opt.MapFrom(s => s.PaisFeriado != null ? s.PaisFeriado.NOMBRE : ""))
                .ForMember(d => d.AreaOrganizativa, opt => opt.MapFrom(s => s.AreaOrganizativa != null ? s.AreaOrganizativa.NOMBRE : ""))
                .ForMember(d => d.EmpresaCorporacion, opt => opt.MapFrom(s => s.EmpresaCorporacion != null ? s.EmpresaCorporacion.NOMBRE : ""))
                .ForMember(d => d.Canton, opt => opt.MapFrom(s => s.IDCANTON == null ? s.CIUDADRESIDENCIA : s.Canton.NOMBRE))
                .ForMember(d => d.Edad, opt => opt.MapFrom(s => _dateTime.Seniority(s.FECHANACIMIENTO, _dateTime.Now)))
                .ForMember(d => d.Antiguedad, opt => opt.MapFrom(s => _dateTime.Seniority(s.FECHAINGRESO, _dateTime.Now)))
                .ForMember(d => d.DeliveryManager, opt => opt.MapFrom(s => s.DeliveryManager != null ? s.DeliveryManager.NOMBRE + " " + s.DeliveryManager.PRIMERAPELLIDO + " " + s.DeliveryManager.SEGUNDOAPELLIDO : ""))
                .ForMember(d => d.IdDeliveryManager, opt => opt.MapFrom(s => s.DeliveryManager != null ? s.DeliveryManager.IDCOLABORADOR : 0))
                .ForMember(d => d.UbicadoEn, opt => opt.MapFrom(s => s.Cliente != null ? s.Cliente.NOMBRE : ""))
                .ForMember(d => d.CIUDADRESIDENCIA, opt => opt.MapFrom(s => s.CIUDADRESIDENCIA))
                .ForMember(d => d.Afiliaciones, opt => opt.MapFrom(s => s.AfiliacionesColaborador))
                .ForMember(d => d.ESDELIVERYMANAGER, opt => opt.MapFrom(s => s.ESDELIVERYMANAGER))
                .ForMember(d => d.CODIGOPOSTAL, opt => opt.MapFrom(s => s.CODIGOPOSTAL))
                .ForMember(d => d.IDNOMINA, opt => opt.MapFrom(s => s.IDNOMINA))
                .ForMember(d => d.ESSERVICIOPROFESIONAL, opt => opt.MapFrom(s => s.ESSERVICIOPROFESIONAL))
                .ForMember(d => d.CERTIFICADOCPIC, opt => opt.MapFrom(s => s.CERTIFICADOCPIC != null ? $"{s.MIMETYPECPIC}{Convert.ToBase64String(s.CERTIFICADOCPIC)}" : null))
                .ForMember(d => d.FOTO, opt => opt.MapFrom(s => s.FOTO != null ? string.Concat(/*"data:image/jpg;base64,"*/s.MIMETYPEFOTO, Convert.ToBase64String(s.FOTO)) :
                                                                                  (s.GENERO.Equals('M') ? "data:image/png;base64,"
                                                                                                        : "data:image/png;base64,")
                                                          )
                          );
        }


    }
}
